<script>const STATE = /*__STATE__*/null;</script>
<script>
(function () {
  'use strict';

  // Rendered on the server, embedded as JSON, drawn here. No fetch at all.
  //
  // n8n serves webhook HTML with a CSP sandbox and no allow-same-origin, which
  // gives this document an opaque origin: a fetch back to the API would be
  // cross-origin, carry no credentials, and fail. So the data arrives inside
  // the page, actions are plain form posts, and "live" is a reload. Every one
  // of those works whether or not the sandbox is there.
  //
  // Everything that came from the database is untrusted -- applicant handles,
  // error messages, notes -- so nothing here ever uses innerHTML. Text goes in
  // through textContent and links are checked before they become hrefs.

  var REFRESH_SECONDS = 8;
  var ACTION_URL = '/webhook/creator-program/dashboard/action';
  var WF = {
    poller: 'creatorPoller01a', rules: 'creatorRules0000', pipeline: 'creatorPipeline1',
    payout: 'creatorPayout002', errors: 'creatorErrors003', replay: 'creatorReplay004',
    evalwf: 'creatorEval00005', digest: 'creatorDigest006', dashboard: 'creatorDash00007'
  };
  var REPLAYABLE = ['ingest', 'screen', 'onboard', 'track'];

  var S = STATE || sample();
  var isSample = !STATE;

  var nf = new Intl.NumberFormat('es-ES');
  var eur = new Intl.NumberFormat('es-ES', { style: 'currency', currency: 'EUR' });
  var dateFmt = new Intl.DateTimeFormat('es-ES', { day: 'numeric', month: 'short' });
  var timeFmt = new Intl.DateTimeFormat('es-ES', { hour: '2-digit', minute: '2-digit', second: '2-digit' });

  // ---- tiny helpers --------------------------------------------------------

  function h(tag, props) {
    var e = document.createElement(tag);
    props = props || {};
    Object.keys(props).forEach(function (k) {
      var v = props[k];
      if (v == null) return;
      if (k === 'text') e.textContent = String(v);
      else if (k === 'class') e.className = v;
      else e.setAttribute(k, String(v));
    });
    for (var i = 2; i < arguments.length; i++) {
      var c = arguments[i];
      if (c == null || c === false) continue;
      e.appendChild(typeof c === 'object' ? c : document.createTextNode(String(c)));
    }
    return e;
  }

  function mount(id, node) {
    var root = document.getElementById(id);
    root.textContent = '';
    if (node) root.appendChild(node);
    return root;
  }

  function safeBase(u) {
    try {
      var x = new URL(String(u));
      return x.protocol === 'https:' ? x.origin : null;
    } catch (e) { return null; }
  }

  function safeHref(u) {
    try {
      var x = new URL(String(u));
      return x.protocol === 'https:' ? x.href : null;
    } catch (e) { return null; }
  }

  function wfLink(id, label) {
    var base = safeBase(S.editor_base_url);
    if (!base) return h('span', { class: 'faint', text: label });
    return h('a', { href: base + '/workflow/' + id, target: '_blank', rel: 'noopener', text: label });
  }

  function ago(ts) {
    if (!ts) return '';
    var s = Math.max(0, Math.round((Date.now() - new Date(ts).getTime()) / 1000));
    if (s < 60) return 'hace ' + s + ' s';
    var m = Math.round(s / 60);
    if (m < 60) return 'hace ' + m + ' min';
    var hr = Math.round(m / 60);
    if (hr < 48) return 'hace ' + hr + ' h';
    return 'hace ' + Math.round(hr / 24) + ' d';
  }

  function pct(n) {
    return n == null ? '—' : (Number(n) * 100).toFixed(1).replace('.', ',') + ' %';
  }

  function dec(n, d) {
    return n == null ? '—' : Number(n).toFixed(d).replace('.', ',');
  }

  function euros(cents) {
    return eur.format(Number(cents || 0) / 100);
  }

  // ---- page state carried in the URL hash ---------------------------------
  //
  // The hash survives a reload and needs no storage, which matters because
  // localStorage throws in an opaque-origin document. It carries the scroll
  // position, the paused flag, and a one-shot message after an action.

  var hp = new URLSearchParams(location.hash.slice(1));
  var paused = hp.get('p') === '1';
  var flashKey = hp.get('f');

  function hashFor(extra) {
    var p = new URLSearchParams();
    p.set('y', String(Math.round(window.scrollY)));
    if (paused) p.set('p', '1');
    if (extra) Object.keys(extra).forEach(function (k) { p.set(k, extra[k]); });
    return '#' + p.toString();
  }

  // ---- actions --------------------------------------------------------------
  //
  // Plain HTML forms, and a synchroniser token in each one. Basic auth is
  // attached by the browser to any request for this URL, including one a
  // different site triggers by posting a form here -- so authentication alone
  // does not stop another page from launching a replay. The token only exists
  // inside this rendered page, which another origin cannot read.

  function actionForm(action, label, cls, extra) {
    var f = h('form', { method: 'post', action: ACTION_URL, class: 'inline' });
    f.appendChild(h('input', { type: 'hidden', name: 'action', value: action }));
    f.appendChild(h('input', { type: 'hidden', name: 'token', value: S.action_token || '' }));
    Object.keys(extra || {}).forEach(function (k) {
      f.appendChild(h('input', { type: 'hidden', name: k, value: extra[k] }));
    });
    var b = h('button', { type: 'submit', class: 'btn ' + (cls || ''), text: label });
    if (isSample) { b.disabled = true; b.title = 'No disponible con datos de ejemplo'; }
    f.addEventListener('submit', function () {
      stopTimer();
      b.disabled = true;
      b.textContent = 'Lanzando…';
    });
    f.appendChild(b);
    return f;
  }

  // ---- sections -------------------------------------------------------------

  function renderHeader() {
    document.getElementById('source').textContent = isSample
      ? 'Vista previa con datos de ejemplo'
      : 'En vivo desde n8n · base de datos creator_prod';

    var actions = document.getElementById('actions');
    actions.appendChild(actionForm('eval', 'Evaluar reglas', ''));
    actions.appendChild(actionForm('poll', 'Lanzar captación', 'primary'));
  }

  function renderKpis() {
    var f = S.funnel || {};
    var applicants = (f.accepted || 0) + (f.review || 0) + (f.rejected || 0) + (S.invalid_total || 0);
    var creators = (S.creators || []).length;
    var ev = S.eval;
    var pay = S.payout;
    var open = S.dead_letters_open || 0;

    var kpis = h('div', { style: 'display:contents' });
    function kpi(label, value, foot, tone) {
      kpis.appendChild(h('div', { class: 'kpi ' + (tone || '') },
        h('div', { class: 'l', text: label }),
        h('div', { class: 'v num', text: value }),
        h('div', { class: 'f', text: foot })));
    }

    kpi('Solicitudes', nf.format(applicants), nf.format(f.review || 0) + ' esperando a una persona');
    kpi('Creadores', nf.format(creators), 'con código de seguimiento');
    kpi('Visitas rastreadas', nf.format(S.views_total || 0), 'en ' + nf.format(S.posts_total || 0) + ' posts');
    kpi('A pagar', pay ? euros(pay.total_cents) : '—',
        pay ? periodLabel(pay) : 'ningún periodo calculado');
    kpi('Aciertos de las reglas', ev ? pct(ev.accuracy) : '—',
        ev ? 'macro F1 ' + dec(ev.macro_f1, 2) : 'aún sin evaluar');
    kpi('Fallos pendientes', nf.format(open), open ? 'por revisar' : 'nada pendiente', open ? 'bad' : 'ok');

    mount('kpis', kpis);
  }

  function periodLabel(p) {
    var end = new Date(p.period_end);
    end.setUTCDate(end.getUTCDate() - 1);
    return dateFmt.format(new Date(p.period_start)) + ' – ' + dateFmt.format(end) + ' · ' +
      nf.format(p.creators) + ' creador' + (p.creators === 1 ? '' : 'es');
  }

  function renderFlow() {
    var f = S.funnel || {};
    var applicants = (f.accepted || 0) + (f.review || 0) + (f.rejected || 0) + (S.invalid_total || 0);
    var stages = [
      ['Captación', nf.format(applicants), 'Recoge las solicitudes nuevas del formulario cada 6 horas.', WF.poller],
      ['Evaluación', nf.format(f.accepted || 0) + ' dentro', 'Aplica las reglas: acepta, rechaza o manda a revisión.', WF.rules],
      ['Alta', nf.format((S.creators || []).length), 'Crea la ficha, genera el código y envía la bienvenida.', WF.pipeline],
      ['Seguimiento', nf.format(S.posts_total || 0) + ' posts', 'Busca los posts con su código y guarda las visitas.', WF.pipeline],
      ['Pago', S.payout ? euros(S.payout.total_cents) : '—', 'Calcula lo que se debe cada mes, con freno de seguridad.', WF.payout]
    ];
    var wrap = h('div', { style: 'display:contents' });
    stages.forEach(function (s, i) {
      wrap.appendChild(h('div', { class: 'stage' },
        h('span', { class: 'n', text: i + 1 }),
        h('h3', { text: s[0] }),
        h('div', { class: 'v num', text: s[1] }),
        h('p', { text: s[2] }),
        wfLink(s[3], 'Ver en n8n →')));
    });
    mount('flow', wrap);
  }

  function renderDecisions() {
    var f = S.funnel || {};
    var parts = [
      ['accepted', 'Aceptadas', f.accepted || 0, 'var(--ok)'],
      ['review', 'A revisión', f.review || 0, 'var(--warn)'],
      ['rejected', 'Rechazadas', f.rejected || 0, 'var(--idle)'],
      ['invalid', 'Datos inválidos', S.invalid_total || 0, 'var(--bad)']
    ];
    var total = parts.reduce(function (a, p) { return a + p[2]; }, 0);

    var bar = document.getElementById('bar');
    bar.textContent = '';
    bar.setAttribute('aria-label', parts.map(function (p) { return p[1] + ' ' + p[2]; }).join(', '));
    parts.forEach(function (p) {
      if (!p[2]) return;
      bar.appendChild(h('span', {
